/**
 * @distilled.cloud/twitch -- Twitch API (Helix) SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy models
 * that `scripts/convert.ts` reads out of Twitch's API reference, mirrored as
 * Markdown under `specs/spec-mirror-twitch/specs/api/reference`. Everything
 * else in this folder is hand-written.
 *
 * One module per reference page: `ads`, `analytics`, `bits`, `ccls`,
 * `channel_points`, `channels`, `charity`, `chat`, `clips`, `conduits`,
 * `entitlements`, `eventsub`, `extensions`, `games`, `goals`, `guest_star`,
 * `hype_train`, `moderation`, `polls`, `predictions`, `raids`, `schedule`,
 * `search`, `streams`, `subscriptions`, `teams`, `users`, `videos` and
 * `whispers`. Import each from its subpath.
 *
 * @example
 * ```ts
 * import { Effect, Layer } from "effect";
 * import * as FetchHttpClient from "effect/http/FetchHttpClient";
 * import * as Twitch from "@distilled.cloud/twitch";
 * import * as Channels from "@distilled.cloud/twitch/channels";
 * import * as Users from "@distilled.cloud/twitch/users";
 *
 * const program = Effect.gen(function* () {
 *   const { data: users = [] } = yield* Users.getUsers({ login: ["twitchdev"] });
 *   const { data: channels = [] } = yield* Channels.getChannelInformation({
 *     broadcaster_id: users.map((user) => user.id!),
 *   });
 *   return channels.map((channel) => ({ name: channel.broadcaster_name, game: channel.game_name }));
 * });
 *
 * const Live = Layer.mergeAll(
 *   FetchHttpClient.layer,
 *   Twitch.CredentialsFromEnv,
 * );
 *
 * program.pipe(Effect.provide(Live), Effect.runPromise).then(console.log);
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export { TwitchProtocol, type TwitchOpError, type TwitchOpContext } from "./protocol.ts";
export * as Retry from "./retry.ts";
export { paginateCursor } from "./pagination.ts";
